local function UpsertBiSSource(data, bis)
    data.sources = data.sources or {}
    for _, source in ipairs(data.sources) do
        if source.label == "BiS Gear" then
            source.updated = bis.sourceUpdated or source.updated
            source.url = bis.sourceURL or source.url
            return
        end
    end
    table.insert(data.sources, { label = "BiS Gear", updated = bis.sourceUpdated or "unknown", url = bis.sourceURL })
end

for specID, bis in pairs((AGB.GuideBiSData and AGB.GuideBiSData.specs) or {}) do
    local meta = AGB.SpecIndex and AGB.SpecIndex[specID]
    local data = meta and AGB.Data and AGB.Data[meta.classFile] and AGB.Data[meta.classFile][specID]
    if data and bis and bis.sourceURL then
        data.bis = bis
        UpsertBiSSource(data, bis)
    end
end